"""MCP server: every function decorated with @mcp.tool() is a tool for the agent."""

from mcp.server.mcpserver import MCPServer

mcp = MCPServer("{{name}}")


@mcp.tool()
def greet(name: str) -> str:
    """Greet a person by name."""
    return f"Hello, {name}!"


if __name__ == "__main__":
    # stdio: stdout es el protocolo, no uses print().
    mcp.run()
